# L05 r02 depth fill — idempotent: sets full field values (no appending)
import json
F='/home/claude/ac-mdcu/parts/fill/l05_r02.json'
D=json.load(open(F))
def S(n,**kw):
    q=D[str(n)]
    for k,v in kw.items():
        if k=='wrong':
            q['wrong'].update(v)
        else:
            q[k]=v
def fixlt(n,field):
    q=D[str(n)]
    if isinstance(q[field],list):
        q[field]=[x.replace('in case < 1:3','in case &lt; 1:3') for x in q[field]]
    else:
        q[field]=q[field].replace('in case < 1:3','in case &lt; 1:3')

# ---------- 11 ----------
S(11, why="กรวยผิวส่วนเกินที่ปลายแผล (<b>dog ear</b> หรือ standing cone) เกิดเมื่อกระสวยสั้นกว่าสัดส่วน 1:3 หรือขอบแผลสองข้างยาวไม่เท่ากัน → แก้โดยตัดส่วนเกินออก ซึ่ง<b>ทำให้ปลายแผลยาวขึ้นหรือหักเลี้ยวเสมอ</b> · เมื่อต้องยืดปลายแผลอยู่แล้ว ให้<b>เลือกทิศให้ปลายแผลไปจบที่รอยต่อของ aesthetic unit</b> เช่น ร่องระหว่างจมูกกับแก้ม (nasofacial junction) ตรงนั้นผิวเรียบของจมูกชนผิวนูนของแก้ม เกิดเงาตามธรรมชาติ แผลจึงกลืนไปกับเงา · หลักเดียวกันใช้กับร่องแก้มข้างจมูกถึงมุมปาก (nasolabial fold) และร่องหลังใบหู · ที่แก้มส่วนบนต้องระวังอีกเรื่อง: ถ้ายืดปลายแผลขึ้นหาเปลือกตาหรือปิดแผลแล้วมีแรงดึงในแนวตั้ง เปลือกตาล่างจะถูกดึงลงจนปลิ้น (ectropion) จึงยิ่งควรหันส่วนที่ยืดเข้าหาร่องจมูก-แก้มแทน · การหันปลายแผลให้ขวาง RSTL ได้ผลตรงข้าม คือขอบถูกดึงจนแผลถ่าง · สไลด์หน้า 8 ลายมือ <b>\"Dog ear → ให้ลงไปอยู่ตรง j<sup>n</sup> → เกิดเงา → ไม่เห็นแผล\"</b>")
fixlt(11,'summary')

